import subprocess
def run(args):
    p=subprocess.run(["./executable"]+args, capture_output=True, text=True, timeout=3)
    s=p.stdout
    if s.endswith("\n"): s=s[:-1]
    return s

for fix in [1,2,10,64]:
    for expr in ["0","255","1234567"]:
        out=run(["-b","16","-f",str(fix),expr])
        print(fix, expr, len(out.split('.')[0]), repr(out[:60]))
print()

# negative numbers via --
for base in [10,16,2]:
    for expr in ["-1","-255","-1234","-0.5","0-5"]:
        out=run(["-b",str(base),"--",expr])
        print(base, expr, repr(out))
    print()

# fractional truncation/ algorithm: check digits
for expr in ["0.1","1/3","2/3","1/7","3.1415926535"]:
    for base in [2,10,16]:
        for fix in [1,5,10,20]:
            out=run(["-b",str(base),"-f",str(fix),expr])
            print(f"b{base} f{fix} {expr} -> {out!r}")
    print()
PY
"}

