import subprocess
def run(args):
    p=subprocess.run(["./executable"]+args, capture_output=True, text=True, timeout=3)
    s=p.stdout
    return (s[:-1] if s.endswith("\n") else s), p.stderr, p.returncode

for base in [10,16,2]:
    for expr in ["0-123","0-123456","0-123456789","0-1234567890","0-10^15","0-10^18","0-10^20"]:
        out,err,rc=run(["-b",str(base),expr])
        print(base,expr,repr(out),err)
    print()
# -0 , rounding
for expr in ["0-0","-0","0*-1","-0.00000000001","0-0.00001"]:
    for args in [[expr],["--",expr],["-b","16","--",expr]]:
        out,err,rc=run(args)
        print(args, repr(out), repr(err), rc)
print()
# Rounding crossover
for fix in ["1","2"]:
    for expr in ["999.99","999.999","0.999","9.999"]:
        for base in ["10","16"]:
            out,_,_=run(["-f",fix,"-b",base,expr])
            print(f"f{fix} b{base} {expr} {out!r}")
PY
"}

