use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum CalcError {
    SyntaxUnexpectedToken(char),
    SyntaxUnexpectedCharacter(String),
    SyntaxUnknownFunction(String),
    SyntaxFunctionExpectedParentheses(String),
    SyntaxMismatchedParentheses,
    SyntaxEmptyArgument,
    SyntaxNoPreviousAnswer,
    ParserTooManyOperators,
    ParserTooFewArguments(usize),
    MathDivideByZero,
    DomainOutOfBounds,
    TooLarge,
    Help(String),
}

impl fmt::Display for CalcError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CalcError::SyntaxUnexpectedToken(c) => write!(f, "Syntax Error: Unexpected token: '{}'", c),
            CalcError::SyntaxUnexpectedCharacter(s) => write!(f, "Syntax Error: Unexpected character '{}'", s),
            CalcError::SyntaxUnknownFunction(s) => write!(f, "Syntax Error: Unknown function '{}'", s),
            CalcError::SyntaxFunctionExpectedParentheses(s) => {
                write!(f, "Syntax Error: Function '{}' expected parentheses", s)
            }
            CalcError::SyntaxMismatchedParentheses => write!(f, "Syntax Error: Mismatched parentheses!"),
            CalcError::SyntaxEmptyArgument => write!(f, "Syntax Error: Empty argument"),
            CalcError::SyntaxNoPreviousAnswer => write!(f, "Syntax Error: No previous answer!"),
            CalcError::ParserTooManyOperators => {
                write!(f, "Parser Error: Too many operators, too few operands")
            }
            CalcError::ParserTooFewArguments(n) => {
                write!(f, "Parser Error: To few arguments for function, need {}", n)
            }
            CalcError::MathDivideByZero => write!(f, "Math Error: Divide by zero error!"),
            CalcError::DomainOutOfBounds => write!(f, "Domain Error: Out of bounds!"),
            CalcError::TooLarge => write!(f, "Error: to large to process! Max value: {}", f64::MAX),
            CalcError::Help(s) => write!(f, "{}", s),
        }
    }
}

impl std::error::Error for CalcError {}
RS
cat > src/fxns.rs << 'RS'
use crate::error::CalcError;
use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AngleUnit {
    Degree,
    Radian,
    Gradian,
}

pub fn constants() -> &'static HashMap<&'static str, f64> {
    static MAP: OnceLock<HashMap<&'static str, f64>> = OnceLock::new();
    MAP.get_or_init(|| {
        let mut m = HashMap::new();
        m.insert("pi", std::f64::consts::PI);
        m.insert("e", std::f64::consts::E);
        m
    })
}

pub fn functions() -> &'static HashMap<&'static str, usize> {
    static MAP: OnceLock<HashMap<&'static str, usize>> = OnceLock::new();
    MAP.get_or_init(|| {
        let mut m = HashMap::new();
        for name in [
            "sin", "cos", "tan", "csc", "sec", "cot", "sinh", "cosh", "tanh", "asin", "acos",
            "atan", "acsc", "asec", "acot", "ln", "log2", "log10", "sqrt", "ceil", "floor", "abs",
            "exp", "exp2", "round", "deg", "rad",
        ] {
            m.insert(name, 1usize);
        }
        m.insert("log", 2usize);
        m.insert("nroot", 2usize);
        m
    })
}

pub fn operators() -> &'static HashSet<char> {
    static SET: OnceLock<HashSet<char>> = OnceLock::new();
    SET.get_or_init(|| ['+', '-', '*', '/', '%', '^', '!'].into_iter().collect())
}

pub fn help_string() -> String {
    let mut out = String::new();
    out.push_str("Constants\n");
    for (i, name) in constants().keys().enumerate() {
        if i > 0 && i % 9 == 0 {
            out.push('\n');
        }
        out.push_str(&format!("{:>8}", name));
    }
    out.push_str("\n\nFunctions\n");
    for (i, name) in functions().keys().enumerate() {
        if i > 0 && i % 9 == 0 {
            out.push('\n');
        }
        out.push_str(&format!("{:>8}", name));
    }
    out.push_str("\n\nOperators\n");
    let ops: Vec<String> = operators().iter().map(|c| c.to_string()).collect();
    out.push_str(&ops.join(" "));
    out.push('\n');
    out
}

fn angle_convert(x: f64, angle: AngleUnit) -> f64 {
    match angle {
        AngleUnit::Radian => x,
        AngleUnit::Degree | AngleUnit::Gradian => x.to_radians(),
    }
}

pub fn eval_function(name: &str, args: &[f64], angle: AngleUnit) -> Result<f64, CalcError> {
    let x = args.get(0).copied().unwrap_or(0.0);
    let result = match name {
        "sin" => angle_convert(x, angle).sin(),
        "cos" => angle_convert(x, angle).cos(),
        "tan" => angle_convert(x, angle).tan(),
        "csc" => angle_convert(x, angle).sin().recip(),
        "sec" => angle_convert(x, angle).cos().recip(),
        "cot" => angle_convert(x, angle).tan().recip(),
        "sinh" => x.sinh(),
        "cosh" => x.cosh(),
        "tanh" => x.tanh(),
        "asin" => x.asin(),
        "acos" => x.acos(),
        "atan" => x.atan(),
        "acsc" => x.recip().asin(),
        "asec" => x.recip().acos(),
        "acot" => x.recip().atan(),
        "ln" => x.ln(),
        "log2" => x.log2(),
        "log10" => x.log10(),
        "sqrt" => x.sqrt(),
        "ceil" => x.ceil(),
        "floor" => x.floor(),
        "abs" => x.abs(),
        "exp" => x.exp(),
        "exp2" => x.exp2(),
        "round" => x.round(),
        "deg" => x.to_degrees(),
        "rad" => x.to_radians(),
        "log" => x.log(args.get(1).copied().unwrap_or(0.0)),
        "nroot" => x.powf(1.0 / args.get(1).copied().unwrap_or(0.0)),
        _ => return Err(CalcError::SyntaxUnknownFunction(name.to_owned())),
    };
    if result.is_finite() {
        Ok(result)
    } else {
        Err(CalcError::DomainOutOfBounds)
    }
}

pub fn factorial(x: f64) -> Result<f64, CalcError> {
    if x < 0.0 || x.fract() != 0.0 {
        return Err(CalcError::DomainOutOfBounds);
    }
    let n = x as u64;
    let mut result = 1.0f64;
    let mut i = 2u64;
    while i <= n {
        result *= i as f64;
