{"command":"cat > src/lex.rs << 'RS'
use crate::error::CalcError;
use crate::fxns::{constants, functions};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Op {
    Add,
    Subtract,
    Multiply,
    Divide,
    Modulo,
    Power,
    UnaryPlus,
    UnaryMinus,
    Factorial,
    PrefixFactorial,
}

impl Op {
    pub fn precedence(self) -> u8 {
        match self {
            Op::Add | Op::Subtract => 1,
            Op::Multiply | Op::Divide | Op::Modulo => 2,
            Op::Power => 3,
            Op::Factorial | Op::PrefixFactorial => 4,
            Op::UnaryPlus | Op::UnaryMinus => 5,
        }
    }
    pub fn is_left_associative(self) -> bool {
        match self {
            Op::Power | Op::UnaryPlus | Op::UnaryMinus => false,
            _ => true,
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Number(f64),
    PrevAns(f64),
    Function(String),
    Operator(Op),
    LeftParen,
    RightParen,
    Comma,
}

struct Lexer {
    tokens: Vec<Token>,
    num_buf: String,
    word_buf: String,
    prev_ans: Option<f64>,
    after_comma_sign_run: Option<bool>,
}

impl Lexer {
    fn flush_number(&mut self) -> bool {
        if self.num_buf.is_empty() {
            return false;
        }
        if let Ok(v) = self.num_buf.parse::<f64>() {
            self.tokens.push(Token::Number(v));
            self.num_buf.clear();
            true
        } else {
            false
        }
    }

    fn flush_word_constant(&mut self) -> bool {
        if self.word_buf.is_empty() {
            return false;
        }
        if let Some(v) = constants().get(self.word_buf.as_str()) {
            let v = *v;
            self.tokens.push(Token::Number(v));
            self.word_buf.clear();
            true
        } else {
            false
        }
    }

    fn flush_buffers(&mut self) {
        self.flush_number();
        self.flush_word_constant();
    }

    fn last_can_end(&self) -> bool {
        matches!(
            self.tokens.last(),
            Some(Token::Number(_))
                | Some(Token::PrevAns(_))
                | Some(Token::RightParen)
                | Some(Token::Operator(Op::Factorial))
                | Some(Token::Operator(Op::PrefixFactorial))
        )
    }

    fn pending_attempt(&self) -> bool {
        !self.num_buf.is_empty() || !self.word_buf.is_empty()
    }
}

pub fn lex(input: &str, prev_ans: Option<f64>) -> Result<Vec<Token>, CalcError> {
    let chars: Vec<char> = input.chars().collect();
    let mut lx = Lexer {
        tokens: Vec::new(),
        num_buf: String::new(),
        word_buf: String::new(),
        prev_ans,
        after_comma_sign_run: None,
    };
    let mut i = 0usize;
    while i < chars.len() {
        let c = chars[i];
        if !(c == '+' || c == '-') && c != ',' {
            // Any non-sign character ends a special run of signs following a comma.
            // A comma itself establishes a new run below.
            lx.after_comma_sign_run = None;
        }
        if c.is_ascii_digit() || c == '.' {
            if !lx.word_buf.is_empty() {
                if c.is_ascii_digit() {
                    let candidate = format!("{}{}", lx.word_buf, c);
                    if functions().contains_key(candidate.as_str())
                        || functions().keys().any(|name| name.starts_with(&candidate))
                    {
                        lx.word_buf.push(c);
                        i += 1;
                        continue;
                    }
                }
                if functions().contains_key(lx.word_buf.as_str()) {
                    return Err(CalcError::SyntaxFunctionExpectedParentheses(
                        lx.word_buf.clone(),
                    ));
                }
                if let Some(v) = constants().get(lx.word_buf.as_str()) {
                    let v = *v;
                    lx.tokens.push(Token::Number(v));
                    lx.tokens.push(Token::Operator(Op::Multiply));
                    lx.word_buf.clear();
                    lx.num_buf.push(c);
                    i += 1;
                    continue;
                }
                return Err(CalcError::SyntaxUnexpectedCharacter(format!(
                    "{}{}",
                    lx.word_buf, c
                )));
            }
            lx.num_buf.push(c);
        } else if c.is_ascii_alphabetic() {
            if !lx.num_buf.is_empty() && lx.flush_number() {
                lx.tokens.push(Token::Operator(Op::Multiply));
            }
            lx.word_buf.push(c);
        } else if c == '_' {
            let value = match lx.prev_ans {
                Some(v) => v,
                None => return Err(CalcError::SyntaxNoPreviousAnswer),
            };
            if !lx.word_buf.is_empty() {
                if functions().contains_key(lx.word_buf.as_str()) {
                    return Err(CalcError::SyntaxFunctionExpectedParentheses(
                        lx.word_buf.clone(),
                    ));
                } else {
                    return Err(CalcError::SyntaxUnexpectedCharacter(lx.word_buf.clone()));
                }
            }
            if lx.flush_number() {
                lx.tokens.push(Token::Operator(Op::Multiply));
            }
            lx.tokens.push(Token::PrevAns(value));
        } else if c == '(' {
            if !lx.word_buf.is_empty() {
                if functions().contains_key(lx.word_buf.as_str()) {
                    let name = std::mem::take(&mut lx.word_buf);
                    lx.tokens.push(Token::Function(name));
                } else {
                    return Err(CalcError::SyntaxUnknownFunction(lx.word_buf.clone()));
                }
            } else {
                let emitted = lx.flush_number();
                if emitted {
                    lx.tokens.push(Token::Operator(Op::Multiply));
                } else if matches!(lx.tokens.last(), Some(Token::RightParen)) {
                    lx.tokens.push(Token::Operator(Op::Multiply));
                }
            }
            lx.tokens.push(Token::LeftParen);
        } else if c == ')' {
            lx.flush_buffers();
            lx.tokens.push(Token::RightParen);
        } else if c == ',' {
            let pending = lx.pending_attempt();
            lx.flush_buffers();
            let can_end_before = pending || lx.last_can_end();
            lx.tokens.push(Token::Comma);
            lx.after_comma_sign_run = Some(can_end_before);
        } else if c == '+' || c == '-' {
            let pending = lx.pending_attempt();
            lx.flush_buffers();
            let is_binary = if let Some(arg_existed) = lx.after_comma_sign_run {
                arg_existed
            } else {
                pending || lx.last_can_end()
            };
            let op = match (c, is_binary) {
                ('+', true) => Op::Add,
                ('+', false) => Op::UnaryPlus,
                ('-', true) => Op::Subtract,
                _ => Op::UnaryMinus,
            };
            lx.tokens.push(Token::Operator(op));
            // Preserve after_comma_sign_run across consecutive signs.
        } else if c == '*' {
            lx.flush_buffers();
            if i + 1 < chars.len() && chars[i + 1] == '*' {
                lx.tokens.push(Token::Operator(Op::Power));
                i += 1;
            } else {
                lx.tokens.push(Token::Operator(Op::Multiply));
            }
        } else if c == '/' {
            lx.flush_buffers();
            lx.tokens.push(Token::Operator(Op::Divide));
        } else if c == '%' {
            lx.flush_buffers();
            lx.tokens.push(Token::Operator(Op::Modulo));
        } else if c == '^' {
            lx.flush_buffers();
            lx.tokens.push(Token::Operator(Op::Power));
        } else if c == '!' {
            lx.flush_buffers();
            if lx.last_can_end() {
                lx.tokens.push(Token::Operator(Op::Factorial));
            } else {
                lx.tokens.push(Token::Operator(Op::PrefixFactorial));
            }
        } else {
            return Err(CalcError::SyntaxUnexpectedToken(c));
        }
        i += 1;
    }
    lx.flush_number();
    lx.flush_word_constant();
    Ok(lx.tokens)
}
