            }
        } else if c == '/' {
            lx.flush_buffers();
            lx.tokens.push(Token::Operator(Op::Divide));
        } else if c == '%' {
            lx.flush_buffers();
            lx.tokens.push(Token::Operator(Op::Modulo));
        } else if c == '^' {
            lx.flush_buffers();
            lx.tokens.push(Token::Operator(Op::Power));
        } else if c == '!' {
            lx.flush_buffers();
            if lx.last_can_end() {
                lx.tokens.push(Token::Operator(Op::Factorial));
            } else {
                lx.tokens.push(Token::Operator(Op::PrefixFactorial));
            }
        } else {
            return Err(CalcError::SyntaxUnexpectedToken(c));
        }
        i += 1;
    }
    lx.flush_number();
    lx.flush_word_constant();
    Ok(lx.tokens)
}
