use crate::error::CalcError;
use crate::fxns::{eval_function, factorial, functions, AngleUnit};
use crate::lex::{lex, Op, Token};

pub fn eval(input: &str, prev_ans: Option<f64>, angle: AngleUnit) -> Result<f64, CalcError> {
    let cleaned = input.trim().replace(' ', "");
    if cleaned == "help" {
        return Err(CalcError::Help(crate::fxns::help_string()));
    }
    if cleaned.is_empty() {
        return Ok(0.0);
    }
    let mut tokens = lex(&cleaned, prev_ans)?;
    // Auto-balance missing closing parentheses.
    let lp = tokens.iter().filter(|t| matches!(t, Token::LeftParen)).count();
    let rp = tokens.iter().filter(|t| matches!(t, Token::RightParen)).count();
    if lp > rp {
        for _ in 0..(lp - rp) {
            tokens.push(Token::RightParen);
        }
    }
    let postfix = infix_to_postfix(tokens)?;
    eval_postfix(postfix, angle)
}

fn infix_to_postfix(tokens: Vec<Token>) -> Result<Vec<Token>, CalcError> {
    let mut output: Vec<Token> = Vec::new();
    let mut stack: Vec<Token> = Vec::new();
    let mut prev: Option<Token> = None;
    for token in tokens {
        match &token {
            Token::Number(v) => output.push(Token::Number(*v)),
            Token::PrevAns(v) => output.push(Token::Number(*v)),
            Token::Function(_) => stack.push(token.clone()),
            Token::Comma => {
                if matches!(prev, Some(Token::Comma)) {
                    return Err(CalcError::SyntaxEmptyArgument);
                }
                let mut found = false;
                while let Some(top) = stack.last() {
                    if matches!(top, Token::LeftParen) {
                        found = true;
                        break;
                    }
                    if matches!(top, Token::Operator(_)) {
                        output.push(stack.pop().unwrap());
                    } else {
                        break;
                    }
                }
                if !found {
                    return Err(CalcError::SyntaxMismatchedParentheses);
                }
                let lp_index = stack.len() - 1;
                if lp_index > 0 && !matches!(stack[lp_index - 1], Token::Function(_)) {
                    stack.pop();
                }
            }
            Token::Operator(op) => {
                let op = *op;
                while let Some(Token::Operator(top_op)) = stack.last().cloned() {
                    if top_op.precedence() > op.precedence()
                        || (top_op.precedence() == op.precedence() && op.is_left_associative())
                    {
                        output.push(stack.pop().unwrap());
                    } else {
                        break;
                    }
                }
                stack.push(Token::Operator(op));
            }
            Token::LeftParen => stack.push(Token::LeftParen),
            Token::RightParen => {
                while let Some(Token::Operator(_)) = stack.last() {
                    output.push(stack.pop().unwrap());
                }
                if matches!(stack.last(), Some(Token::LeftParen)) {
                    stack.pop();
                } else {
                    return Err(CalcError::SyntaxMismatchedParentheses);
                }
                if matches!(stack.last(), Some(Token::Function(_))) {
                    output.push(stack.pop().unwrap());
                }
            }
        }
        prev = Some(token);
    }
    while let Some(token) = stack.pop() {
        match token {
            Token::LeftParen => return Err(CalcError::SyntaxMismatchedParentheses),
            Token::Operator(_) | Token::Function(_) => output.push(token),
            _ => {}
        }
    }
    Ok(output)
}

fn check_finite_operator(result: f64) -> Result<f64, CalcError> {
    if result.is_finite() {
        Ok(result)
    } else {
        Err(CalcError::TooLarge)
    }
}

fn eval_postfix(tokens: Vec<Token>, angle: AngleUnit) -> Result<f64, CalcError> {
    if tokens.is_empty() {
        return Err(CalcError::ParserTooManyOperators);
    }
    let mut stack: Vec<f64> = Vec::new();
    for token in tokens {
        match token {
            Token::Number(v) | Token::PrevAns(v) => stack.push(v),
            Token::Function(name) => {
                let arity = functions().get(name.as_str()).copied().unwrap_or(1);
                if stack.len() < arity {
                    return Err(CalcError::ParserTooFewArguments(arity));
                }
                let mut args = vec![0.0; arity];
                for idx in (0..arity).rev() {
                    args[idx] = stack.pop().unwrap();
                }
                let result = eval_function(&name, &args, angle)?;
                stack.push(result);
            }
            Token::Operator(op) => match op {
                Op::UnaryPlus => {
                    let x = stack.pop().ok_or(CalcError::ParserTooManyOperators)?;
                    stack.push(check_finite_operator(x)?);
                }
                Op::UnaryMinus => {
                    let x = stack.pop().ok_or(CalcError::ParserTooManyOperators)?;
                    stack.push(check_finite_operator(-x)?);
                }
                Op::Factorial => {
                    let x = stack.pop().ok_or(CalcError::ParserTooManyOperators)?;
                    let result = factorial(x)?;
                    stack.push(check_finite_operator(result)?);
                }
                Op::PrefixFactorial => {
                    let _x = stack.pop().ok_or(CalcError::ParserTooManyOperators)?;
                    stack.push(1.0);
                }
                Op::Add | Op::Subtract | Op::Multiply | Op::Divide | Op::Modulo | Op::Power => {
                    if stack.len() < 2 {
                        return Err(CalcError::ParserTooManyOperators);
                    }
                    let rhs = stack.pop().unwrap();
                    let lhs = stack.pop().unwrap();
                    if op == Op::Divide && rhs == 0.0 {
                        return Err(CalcError::MathDivideByZero);
                    }
                    let result = match op {
                        Op::Add => lhs + rhs,
                        Op::Subtract => lhs - rhs,
                        Op::Multiply => lhs * rhs,
                        Op::Divide => lhs / rhs,
                        Op::Modulo => lhs % rhs,
                        Op::Power => lhs.powf(rhs),
                        _ => unreachable!(),
                    };
                    stack.push(check_finite_operator(result)?);
                }
            },
            _ => {}
        }
    }
    if stack.len() != 1 {
        return Err(CalcError::ParserTooManyOperators);
    }
    Ok(stack[0])
}
RS
"}

