pub fn format_number(number: f64, radix: u32, fix: usize) -> String {
    let formatted = format!("{:.*}", fix, number);
    if radix == 10 {
        return add_commas_to_decimal(&formatted);
    }
    let (int_part, frac_part) = match formatted.split_once('.') {
        Some(parts) => parts,
        None => return formatted,
    };
    let (negative, int_digits) = if let Some(stripped) = int_part.strip_prefix('-') {
        (true, stripped)
    } else {
        (false, int_part)
    };
    let mut int_radix = convert_decimal_integer(int_digits, radix);
    if negative {
        int_radix = format!("-{}", int_radix);
    }
    let padded = format!("{:>10}", int_radix);
    let int_formatted = add_commas(&padded);
    let fraction_value: f64 = format!("0.{}", frac_part).parse().unwrap_or(0.0);
    let frac_radix = convert_fraction(fraction_value, radix, fix);
    let frac_display = if frac_radix.is_empty() { "0" } else { &frac_radix };
    format!("{}.{}", int_formatted, frac_display)
}

pub fn rounded_decimal_value(number: f64, fix: usize) -> f64 {
    format!("{:.*}", fix, number).parse::<f64>().unwrap_or(number)
}

fn add_commas_to_decimal(formatted: &str) -> String {
    if let Some((int_part, frac_part)) = formatted.split_once('.') {
        format!("{}.{}", add_commas(int_part), frac_part)
    } else {
        formatted.to_owned()
    }
}

fn add_commas(value: &str) -> String {
    let (sign, rest) = if let Some(stripped) = value.strip_prefix('-') {
        ("-", stripped)
    } else {
        ("", value)
    };
    let mut reversed = String::new();
    for (i, ch) in rest.chars().rev().enumerate() {
        if i > 0 && i % 3 == 0 {
            reversed.push(',');
        }
        reversed.push(ch);
    }
    format!("{}{}", sign, reversed.chars().rev().collect::<String>())
}

fn digit_char(digit: u32) -> char {
    std::char::from_digit(digit, 36).unwrap_or('0').to_ascii_uppercase()
}

fn convert_decimal_integer(digits: &str, radix: u32) -> String {
    let mut current: Vec<u8> = digits.bytes().map(|b| b.saturating_sub(b'0')).collect();
    if current.is_empty() || current.iter().all(|d| *d == 0) {
        return "0".to_owned();
    }
    let mut reversed = Vec::new();
    while !(current.len() == 1 && current[0] == 0) {
        let mut remainder = 0u32;
        let mut next: Vec<u8> = Vec::with_capacity(current.len());
        for d in &current {
            let cur = remainder * 10 + *d as u32;
            let quotient = cur / radix;
            remainder = cur % radix;
            if !next.is_empty() || quotient != 0 {
                next.push(quotient as u8);
            }
        }
        if next.is_empty() {
            next.push(0);
        }
        reversed.push(digit_char(remainder));
        current = next;
    }
    reversed.iter().rev().collect()
}

fn convert_fraction(mut fraction: f64, radix: u32, fix: usize) -> String {
    let mut out = String::new();
    for _ in 0..fix {
        if fraction == 0.0 {
            break;
        }
        fraction *= radix as f64;
        let digit = fraction.trunc();
        out.push(digit_char(digit as u32));
        fraction -= digit;
    }
    out
}
