use std::fs;
use std::io::{self, BufRead, BufReader};
use std::path::{Path, PathBuf};

#[derive(Debug)]
pub enum HistoryError {
    Io(io::Error),
}

impl From<io::Error> for HistoryError {
    fn from(e: io::Error) -> Self {
        HistoryError::Io(e)
    }
}

const MAX_HISTORY: usize = 1000;

#[derive(Debug, Default)]
pub struct History {
    pub entries: Vec<String>,
    dirty: bool,
}

impl History {
    pub fn load(&mut self, path: &Path) -> Result<(), HistoryError> {
        let file = fs::File::open(path)?;
        let reader = BufReader::new(file);
        let mut lines = reader.lines();
        let first = match lines.next() {
            Some(Ok(line)) => line,
            Some(Err(e)) => return Err(HistoryError::Io(e)),
            None => return Ok(()),
        };
        let version2 = first == "#V2";
        if !version2 {
            self.add_loaded(first);
        }
        for line in lines {
            match line {
                Ok(text) => {
                    let entry = if version2 { decode_v2(&text) } else { text };
                    self.add_loaded(entry);
                }
                Err(e) => return Err(HistoryError::Io(e)),
            }
        }
        Ok(())
    }

    fn add_loaded(&mut self, entry: String) {
        self.add_internal(&entry, false);
    }

    pub fn add(&mut self, entry: &str) -> bool {
        self.add_internal(entry, true)
    }

    fn add_internal(&mut self, entry: &str, mark_dirty: bool) -> bool {
        if entry.is_empty() {
            return false;
        }
        if entry.chars().next().map(|c| c.is_whitespace()).unwrap_or(false) {
            return false;
        }
        if self.entries.last().map(|s| s.as_str()) == Some(entry) {
            return false;
        }
        self.entries.push(entry.to_owned());
        if self.entries.len() > MAX_HISTORY {
            self.entries.remove(0);
        }
        if mark_dirty {
            self.dirty = true;
        }
        true
    }

    pub fn save(&self, path: &Path) -> Result<(), HistoryError> {
        if !self.dirty {
            return Ok(());
        }
        let mut output = String::from("#V2\n");
        for entry in &self.entries {
            output.push_str(&encode_v2(entry));
            output.push('\n');
        }
        fs::write(path, output)?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = fs::set_permissions(path, fs::Permissions::from_mode(0o600));
        }
        Ok(())
    }
}

fn decode_v2(text: &str) -> String {
    let mut result = String::new();
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.peek() {
                Some('n') => {
                    chars.next();
                    result.push('\n');
                }
                Some('\\') => {
                    chars.next();
                    result.push('\\');
                }
                _ => result.push('\\'),
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn encode_v2(text: &str) -> String {
    let mut result = String::new();
    for c in text.chars() {
        match c {
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            _ => result.push(c),
        }
    }
    result
}

pub fn app_directory(base: Option<PathBuf>) -> PathBuf {
    if let Some(base) = base {
        let dir = base.join("eva");
        if fs::create_dir_all(&dir).is_ok() && dir.is_dir() {
            return dir;
        }
    }
    #[allow(deprecated)]
    std::env::home_dir().unwrap_or_else(|| PathBuf::from("."))
}

pub fn data_base_dir() -> Option<PathBuf> {
    xdg_base_dir("XDG_DATA_HOME", ".local/share")
}

pub fn cache_base_dir() -> Option<PathBuf> {
    xdg_base_dir("XDG_CACHE_HOME", ".cache")
}

fn xdg_base_dir(var: &str, fallback_suffix: &str) -> Option<PathBuf> {
    if let Some(value) = std::env::var_os(var) {
        if !value.is_empty() {
            let path = PathBuf::from(value);
            if path.is_absolute() {
                return Some(path);
            }
        }
    }
    #[allow(deprecated)]
    std::env::home_dir().map(|home| home.join(fallback_suffix))
}
RS
"}

