use crate::fxns::{constants, functions, AngleUnit};
use crate::parse::eval;

pub fn highlight_line(line: &str, angle: AngleUnit) -> String {
    if line.trim().replace(' ', "") == "help" {
        if let Some(idx) = line.find("help") {
            let mut out = String::new();
            out.push_str(&line[..idx]);
            out.push_str("\x1b[36mhelp\x1b[0m");
            out.push_str(&line[idx + 4..]);
            return out;
        }
        return line.to_owned();
    }
    if eval(line, None, angle).is_err() {
        if line.is_empty() {
            return String::new();
        }
        return format!("\x1b[31m{}\x1b[0m", line);
    }
    colorize(line)
}

fn color_segment(code: u8, text: &str) -> String {
    format!("\x1b[{}m{}\x1b[0m", code, text)
}

fn colorize(line: &str) -> String {
    let chars: Vec<char> = line.chars().collect();
    let mut out = String::new();
    let mut i = 0usize;
    while i < chars.len() {
        let c = chars[i];
        if c.is_ascii_alphabetic() {
            let start = i;
            while i < chars.len() && chars[i].is_ascii_alphabetic() {
                i += 1;
            }
            let word: String = chars[start..i].iter().collect();
            // Optional immediate digit run, used only toRecognize names such as log10.
            let digit_start = i;
            let mut digit_end = i;
            while digit_end < chars.len() && chars[digit_end].is_ascii_digit() {
                digit_end += 1;
            }
            let digits: String = chars[digit_start..digit_end].iter().collect();
            let candidate = format!("{}{}", word, digits);
            if functions().contains_key(candidate.as_str())
                && digit_end < chars.len()
                && chars[digit_end] == '('
            {
                out.push_str(&color_segment(34, &candidate));
                i = digit_end;
                continue;
            }
            if constants().contains_key(word.as_str())
                && !(i < chars.len() && chars[i].is_ascii_digit())
            {
                out.push_str(&color_segment(33, &word));
            } else {
                out.push_str(&word);
            }
            continue;
        }
        if matches!(c, '+' | '-' | '*' | '/' | '%' | '^' | '!' | '.' | ',') {
            out.push_str(&color_segment(35, &c.to_string()));
            i += 1;
            continue;
        }
        out.push(c);
        i += 1;
    }
    out
}
