            Event::Control(3) => return Ok(Some(Outcome::Interrupted)),
            _ => {
                // Leave search mode, using the matched line (if any), then
                // process this event as a normal editing command.
                let (line, cursor) = self.search_display_line(&search);
                state.chars = line.chars().collect();
                state.cursor = cursor;
                state.search = None;
                // Fall through to normal event processing in caller.
            }
        }
        Ok(None)
    }

    fn search_display_line(&self, search: &SearchState) -> (String, usize) {
        if let Some(index) = search.match_index {
            if let Some(entry) = self.history.entries.get(index) {
                return (entry.clone(), search.match_pos);
            }
        }
        (
            search.original.iter().collect(),
            search.original_cursor,
        )
    }

    fn update_search(&self, search: &mut SearchState, from_current: bool) {
        if search.query.is_empty() {
            search.match_index = None;
            search.failed = false;
            return;
        }
        match search.direction {
            SearchDirection::Reverse => {
                let start = if from_current {
                    search
                        .match_index
                        .unwrap_or_else(|| self.history.entries.len().saturating_sub(1))
                } else {
                    self.history.entries.len().saturating_sub(1)
                };
                if self.history.entries.is_empty() {
                    search.failed = true;
                    return;
                }
                for index in (0..=start).rev() {
                    if let Some(pos) = self.history.entries[index].find(&search.query) {
                        search.match_index = Some(index);
                        search.match_pos = self.history.entries[index][..pos].chars().count();
                        search.failed = false;
                        return;
                    }
                }
                search.failed = true;
            }
            SearchDirection::Forward => {
                let start = if from_current {
                    search.match_index.unwrap_or(0)
                } else {
                    0
                };
                for index in start..self.history.entries.len() {
                    if let Some(pos) = self.history.entries[index].find(&search.query) {
                        search.match_index = Some(index);
                        search.match_pos = self.history.entries[index][..pos].chars().count();
                        search.failed = false;
                        return;
                    }
                }
                search.failed = true;
            }
        }
    }

    fn step_search(&self, search: &mut SearchState, direction: SearchDirection) {
        if search.query.is_empty() || self.history.entries.is_empty() {
            search.failed = true;
            return;
        }
        match direction {
            SearchDirection::Reverse => {
                let start = match search.match_index {
                    Some(0) => {
                        search.failed = true;
                        return;
                    }
                    Some(index) => index - 1,
                    None => self.history.entries.len() - 1,
                };
                for index in (0..=start).rev() {
                    if let Some(pos) = self.history.entries[index].find(&search.query) {
                        search.match_index = Some(index);
                        search.match_pos = self.history.entries[index][..pos].chars().count();
                        search.failed = false;
                        return;
                    }
                }
                search.failed = true;
            }
            SearchDirection::Forward => {
                let start = match search.match_index {
                    Some(index) if index + 1 < self.history.entries.len() => index + 1,
                    Some(_) => {
                        search.failed = true;
                        return;
                    }
                    None => 0,
                };
                for index in start..self.history.entries.len() {
                    if let Some(pos) = self.history.entries[index].find(&search.query) {
                        search.match_index = Some(index);
                        search.match_pos = self.history.entries[index][..pos].chars().count();
                        search.failed = false;
                        return;
                    }
                }
                search.failed = true;
            }
        }
    }

    fn handle_normal_event(
        &mut self,
        out: &mut io::Stdout,
        renderer: &mut Renderer,
        state: &mut LineState,
        event: Event,
    ) -> Result<Option<Outcome>, ReadlineError> {
        if state.quoted_insert && !matches!(event, Event::Paste(_)) {
            state.quoted_insert = false;
            match event {
                Event::Char(c) => {
                    self.insert_text(state, &c.to_string());
                    self.render(out, renderer, state);
                    return Ok(None);
                }
                Event::Control(b) => {
                    if (1..=31).contains(&b) {
                        self.insert_text(state, &(b as char).to_string());
                        self.render(out, renderer, state);
                        return Ok(None);
                    }
                }
                Event::Tab => {
                    self.insert_text(state, "\t");
                    self.render(out, renderer, state);
                    return Ok(None);
                }
                _ => {}
            }
        }
        if is_enter_event(&event) {
            state.cursor = state.chars.len();
            self.render(out, renderer, state);
            return Ok(Some(Outcome::Line(state.text())));
        }
        match event {
            Event::Eof => return Ok(Some(Outcome::Eof)),
            Event::None => {}
            Event::Char(c) => {
                self.insert_text(state, &c.to_string());
                self.render(out, renderer, state);
            }
            Event::Paste(text) => {
                self.insert_text(state, &text);
                self.render(out, renderer, state);
            }
            Event::Backspace => {
                if state.cursor > 0 {
                    state.push_undo();
                    state.cursor -= 1;
                    state.chars.remove(state.cursor);
                    self.render(out, renderer, state);
                } else {
                    self.beep(out);
                }
            }
            Event::Delete => {
                if state.cursor < state.chars.len() {
                    state.push_undo();
                    state.chars.remove(state.cursor);
                }
                self.render(out, renderer, state);
            }
            Event::Left => {
                if state.cursor > 0 {
                    state.cursor -= 1;
                    self.render(out, renderer, state);
                }
            }
            Event::Right => {
                if state.cursor < state.chars.len() {
                    state.cursor += 1;
                    self.render(out, renderer, state);
                } else {
                    let hint = self.hint(state);
                    if !hint.is_empty() {
                        self.insert_text(state, &hint);
                        self.render(out, renderer, state);
                    }
                }
            }
            Event::WordLeft => {
                let new = word_left(&state.chars, state.cursor);
                if new != state.cursor {
                    state.cursor = new;
                    self.render(out, renderer, state);
                }
            }
            Event::WordRight => {
                let new = word_right(&state.chars, state.cursor);
                if new != state.cursor {
                    state.cursor = new;
                    self.render(out, renderer, state);
                }
            }
            Event::Home => {
                if state.cursor != 0 {
                    state.cursor = 0;
                    self.render(out, renderer, state);
                }
            }
            Event::End => {
                if state.cursor != state.chars.len() {
                    state.cursor = state.chars.len();
                    self.render(out, renderer, state);
                }
            }
            Event::Up => self.history_move(out, renderer, state, true, false),
            Event::Down => self.history_move(out, renderer, state, false, false),
            Event::PageUp => self.history_move(out, renderer, state, true, true),
            Event::PageDown => self.history_move(out, renderer, state, false, true),
            Event::Tab => self.complete(out, renderer, state, false),
            Event::BackTab => self.complete(out, renderer, state, true),
            Event::Escape => {}
            Event::AltBackspace => {
                let start = word_left(&state.chars, state.cursor);
                if start < state.cursor {
                    state.push_undo();
                    self.kill_buffer = state.chars[start..state.cursor].iter().collect();
                    state.chars.drain(start..state.cursor);
                    state.cursor = start;
                    self.render(out, renderer, state);
                }
            }
            Event::AltChar(c) => self.handle_alt(out, renderer, state, c),
            Event::Control(1) => {
                if state.cursor != 0 {
                    state.cursor = 0;
                    self.render(out, renderer, state);
                }
            }
            Event::Control(2) => {
                if state.cursor > 0 {
                    state.cursor -= 1;
                    self.render(out, renderer, state);
                }
            }
            Event::Control(3) => return Ok(Some(Outcome::Interrupted)),
            Event::Control(4) => {
                if state.chars.is_empty() {
                    self.render(out, renderer, state);
                    return Ok(Some(Outcome::Eof));
                }
                if state.cursor < state.chars.len() {
                    state.push_undo();
                    state.chars.remove(state.cursor);
                }
                self.render(out, renderer, state);
            }
            Event::Control(5) => {
                if state.cursor != state.chars.len() {
                    state.cursor = state.chars.len();
                    self.render(out, renderer, state);
                }
            }
            Event::Control(6) => {
                if state.cursor < state.chars.len() {
                    state.cursor += 1;
                    self.render(out, renderer, state);
                }
            }
            Event::Control(7) => {}
            Event::Control(11) => {
                if state.cursor < state.chars.len() {
                    state.push_undo();
                    self.kill_buffer =
                        state.chars[state.cursor..].iter().collect::<String>();
                    state.chars.truncate(state.cursor);
                    self.render(out, renderer, state);
                }
            }
            Event::Control(12) => {
                renderer.clear_screen = true;
                self.render(out, renderer, state);
            }
            Event::Control(14) => self.history_move(out, renderer, state, false, false),
            Event::Control(16) => self.history_move(out, renderer, state, true, false),
            Event::Control(18) => {
                state.search = Some(SearchState {
                    query: String::new(),
                    direction: SearchDirection::Reverse,
                    failed: false,
                    match_index: None,
                    match_pos: 0,
                    original: state.chars.clone(),
                    original_cursor: state.cursor,
                });
                self.render(out, renderer, state);
            }
            Event::Control(19) => {
                state.search = Some(SearchState {
                    query: String::new(),
                    direction: SearchDirection::Forward,
                    failed: false,
                    match_index: None,
                    match_pos: 0,
                    original: state.chars.clone(),
                    original_cursor: state.cursor,
                });
                self.render(out, renderer, state);
            }
            Event::Control(20) => {
                if state.chars.len() >= 2 && state.cursor > 0 {
                    state.push_undo();
                    if state.cursor == state.chars.len() {
                        let len = state.chars.len();
                        state.chars.swap(len - 2, len - 1);
                    } else {
                        state.chars.swap(state.cursor - 1, state.cursor);
                        state.cursor += 1;
                    }
                    self.render(out, renderer, state);
                }
            }
            Event::Control(21) => {
                if !state.chars.is_empty() {
                    state.push_undo();
                    self.kill_buffer = state.text();
                    state.chars.clear();
                    state.cursor = 0;
                    self.render(out, renderer, state);
                }
            }
            Event::Control(22) => {
                state.quoted_insert = true;
            }
            Event::Control(23) => {
                let start = kill_word_left(&state.chars, state.cursor);
                if start < state.cursor {
                    state.push_undo();
                    self.kill_buffer = state.chars[start..state.cursor].iter().collect();
                    state.chars.drain(start..state.cursor);
                    state.cursor = start;
                    self.render(out, renderer, state);
                }
            }
            Event::Control(25) => {
                if !self.kill_buffer.is_empty() {
                    let text = self.kill_buffer.clone();
                    self.insert_text(state, &text);
                    self.render(out, renderer, state);
                }
            }
            Event::Control(31) => {
                if let Some((chars, cursor)) = state.undo.pop() {
                    state.chars = chars;
                    state.cursor = cursor;
                    self.render(out, renderer, state);
                } else {
                    self.beep(out);
                }
            }
            Event::Control(_) => {}
        }
        Ok(None)
    }

    fn handle_alt(
        &mut self,
        out: &mut io::Stdout,
        renderer: &mut Renderer,
        state: &mut LineState,
        c: char,
    ) {
        match c {
            'b' => {
                let new = word_left(&state.chars, state.cursor);
                if new != state.cursor {
                    state.cursor = new;
                    self.render(out, renderer, state);
                }
            }
            'f' => {
                let new = word_right(&state.chars, state.cursor);
                if new != state.cursor {
                    state.cursor = new;
                    self.render(out, renderer, state);
                }
            }
            'd' => {
                let end = word_right(&state.chars, state.cursor);
                if end > state.cursor {
                    state.push_undo();
                    self.kill_buffer =
                        state.chars[state.cursor..end].iter().collect::<String>();
                    state.chars.drain(state.cursor..end);
                    self.render(out, renderer, state);
                }
            }
            '<' => self.history_move(out, renderer, state, true, true),
            '>' => self.history_move(out, renderer, state, false, true),
            _ => {}
        }
    }

    fn insert_text(&mut self, state: &mut LineState, text: &str) {
        if text.is_empty() {
            return;
        }
        state.push_undo();
        for c in text.chars() {
            state.chars.insert(state.cursor, c);
            state.cursor += 1;
        }
    }

    fn history_move(
        &mut self,
        out: &mut io::Stdout,
        renderer: &mut Renderer,
        state: &mut LineState,
        up: bool,
        jump: bool,
    ) {
        if self.history.entries.is_empty() {
            self.beep(out);
            return;
        }
        if state.browse.is_none() {
            if !up {
                return;
            }
            let mut entries: Vec<Vec<char>> = self
                .history
                .entries
                .iter()
                .map(|s| s.chars().collect())
                .collect();
            entries.push(state.chars.clone());
            let pos = if jump { 0 } else { entries.len() - 2 };
            state.browse = Some(BrowseState { entries, pos });
        } else if let Some(browse) = &mut state.browse {
            browse.entries[browse.pos] = state.chars.clone();
            if up {
                if jump {
                    browse.pos = 0;
                } else if browse.pos > 0 {
                    browse.pos -= 1;
                } else {
                    self.beep(out);
                    return;
                }
            } else if jump {
                browse.pos = browse.entries.len() - 1;
            } else if browse.pos + 1 < browse.entries.len() {
                browse.pos += 1;
            } else {
                return;
            }
        }
        if let Some(browse) = &state.browse {
            state.chars = browse.entries[browse.pos].clone();
            state.cursor = state.chars.len();
            let is_draft = browse.pos == browse.entries.len() - 1;
            if is_draft {
                state.browse = None;
            }
        }
        self.render(out, renderer, state);
    }

    fn complete(
        &mut self,
        out: &mut io::Stdout,
        renderer: &mut Renderer,
        state: &mut LineState,
        reverse: bool,
    ) {
        if state.completion.is_none() {
            let Some((start, original, candidates)) =
                filename_candidates(&state.chars, state.cursor)
            else {
                self.beep(out);
                return;
            };
            if candidates.is_empty() {
                self.beep(out);
                return;
            }
            state.push_undo();
            let index = if reverse {
                candidates.len() - 1
            } else {
                0
            };
            let candidate = candidates[index].clone();
            state.completion = Some(CompletionState {
                start,
                original,
                candidates,
                index: Some(index),
                current: String::new(),
            });
            self.replace_completion(state, &candidate);
            self.render(out, renderer, state);
            return;
        }
        let mut completion = state.completion.take().unwrap();
        let mut to_beep = false;
        let replacement;
        if reverse {
            match completion.index {
                None => {
                    let index = completion.candidates.len() - 1;
                    completion.index = Some(index);
                    replacement = completion.candidates[index].clone();
                }
                Some(0) => {
                    completion.index = None;
                    replacement = completion.original.clone();
                    to_beep = true;
                }
                Some(index) => {
                    completion.index = Some(index - 1);
                    replacement = completion.candidates[index - 1].clone();
                }
            }
        } else {
            match completion.index {
                None => {
                    completion.index = Some(0);
                    replacement = completion.candidates[0].clone();
                }
                Some(index) if index + 1 < completion.candidates.len() => {
                    completion.index = Some(index + 1);
                    replacement = completion.candidates[index + 1].clone();
                }
                Some(_) => {
                    completion.index = None;
                    replacement = completion.original.clone();
                    to_beep = true;
                }
            }
        }
        state.completion = Some(completion);
        self.replace_completion(state, &replacement);
        if to_beep {
            self.beep(out);
        }
        self.render(out, renderer, state);
    }

    fn replace_completion(&mut self, state: &mut LineState, replacement: &str) {
        let Some(completion) = &mut state.completion else {
            return;
        };
        let start = completion.start;
        let current_len = if completion.current.is_empty() {
            completion.original.chars().count()
        } else {
            completion.current.chars().count()
        };
        let end = (start + current_len).min(state.chars.len());
        state.chars.drain(start..end);
        for (offset, c) in replacement.chars().enumerate() {
            state.chars.insert(start + offset, c);
        }
        state.cursor = start + replacement.chars().count();
        completion.current = replacement.to_owned();
    }

    fn hint(&self, state: &LineState) -> String {
        if state.cursor != state.chars.len() || state.chars.is_empty() || state.search.is_some() {
            return String::new();
        }
        let line = state.text();
        for entry in self.history.entries.iter().rev() {
            if entry.len() > line.len() && entry.starts_with(&line) {
                return entry[line.len()..].to_owned();
            }
        }
        String::new()
    }

    fn beep(&mut self, out: &mut io::Stdout) {
        let _ = out.write_all(b"\x07");
        let _ = out.flush();
    }

    fn render(&mut self, out: &mut io::Stdout, renderer: &mut Renderer, state: &LineState) {
        let (prompt, display, cursor) = if let Some(search) = &state.search {
            let prompt = search_prompt(search);
            let (line, cursor) = self.search_display_line(search);
            (prompt, line, cursor)
        } else {
            ("> ".to_owned(), state.text(), state.cursor)
        };
        let hint = if state.search.is_some() {
            String::new()
        } else {
            self.hint(state)
        };
        renderer.render(out, &prompt, &display, cursor, &hint, self.angle);
    }

    fn next_event(&mut self) -> Result<Event, ReadlineError> {
        let Some(first) = self.read_byte()? else {
            return Ok(Event::Eof);
        };
        Self::parse_first_byte(self, first)
    }

    fn parse_first_byte(&mut self, first: u8) -> Result<Event, ReadlineError> {
        match first {
            b'\r' | b'\n' => Ok(Event::Char('\r')),
            0x7f | 0x08 => Ok(Event::Backspace),
            0x09 => Ok(Event::Tab),
            0x1b => self.parse_escape(),
            0x00..=0x1f => Ok(Event::Control(first)),
            0x20..=0x7e => Ok(Event::Char(first as char)),
            _ => {
                let mut bytes = vec![first];
                let needed = utf8_len(first);
                if needed == 0 {
                    return Ok(Event::None);
                }
                for _ in 1..needed {
                    match self.read_byte()? {
                        Some(b) => bytes.push(b),
                        None => break,
                    }
                }
                match std::str::from_utf8(&bytes) {
                    Ok(s) => Ok(s.chars().next().map(Event::Char).unwrap_or(Event::None)),
                    Err(_) => Ok(Event::None),
                }
            }
        }
    }

    fn parse_escape(&mut self) -> Result<Event, ReadlineError> {
        if !self.poll(20) && self.input.is_empty() {
            return Ok(Event::Escape);
        }
        let Some(second) = self.read_byte()? else {
            return Ok(Event::Escape);
        };
        match second {
            b'[' => self.parse_csi(),
            b'O' => {
                let Some(code) = self.read_byte()? else {
                    return Ok(Event::Escape);
                };
                Ok(match code {
                    b'A' => Event::Up,
                    b'B' => Event::Down,
                    b'C' => Event::Right,
                    b'D' => Event::Left,
                    b'H' => Event::Home,
                    b'F' => Event::End,
                    _ => Event::None,
                })
            }
            0x7f | 0x08 => Ok(Event::AltBackspace),
            0x1b => Ok(Event::Escape),
            _ if second < 0x20 => Ok(Event::Control(second)),
            _ if second < 0x80 => Ok(Event::AltChar(second as char)),
            _ => {
                // Decode an Alt-modified UTF-8 character.
                let mut bytes = vec![second];
                let needed = utf8_len(second);
                for _ in 1..needed {
                    if let Some(b) = self.read_byte()? {
                        bytes.push(b);
                    }
                }
                match std::str::from_utf8(&bytes) {
                    Ok(s) => Ok(s
                        .chars()
                        .next()
                        .map(Event::AltChar)
                        .unwrap_or(Event::None)),
                    Err(_) => Ok(Event::None),
                }
            }
        }
    }

    fn parse_csi(&mut self) -> Result<Event, ReadlineError> {
        let mut params = Vec::new();
        loop {
            let Some(byte) = self.read_byte()? else {
                return Ok(Event::Escape);
            };
            if (0x40..=0x7e).contains(&byte) {
                let final_byte = byte;
                let param_text = String::from_utf8_lossy(&params).to_string();
                if final_byte == b'~' && param_text == "200" {
                    return self.parse_paste();
                }
                return Ok(csi_event(&param_text, final_byte));
            }
            params.push(byte);
            if params.len() > 64 {
                return Ok(Event::None);
            }
        }
    }

    fn parse_paste(&mut self) -> Result<Event, ReadlineError> {
        let pattern: [u8; 6] = [0x1b, b'[', b'2', b'0', b'1', b'~'];
        let mut matched = 0usize;
        let mut content: Vec<u8> = Vec::new();
        while let Some(byte) = self.read_byte()? {
            if byte == pattern[matched] {
                matched += 1;
                if matched == pattern.len() {
                    break;
                }
                continue;
            }
            if matched > 0 {
                content.extend_from_slice(&pattern[..matched]);
                matched = 0;
            }
            if byte == pattern[0] {
                matched = 1;
            } else {
                content.push(byte);
            }
        }
        let mut text = String::from_utf8_lossy(&content).to_string();
        text = text.replace("\r\n", "\n").replace('\r', "\n");
        Ok(Event::Paste(text))
    }

    fn read_byte(&mut self) -> Result<Option<u8>, ReadlineError> {
        if let Some(byte) = self.input.pop_front() {
            return Ok(Some(byte));
        }
        let mut buf = [0u8; 8192];
        let count = unsafe {
            libc_read(0, buf.as_mut_ptr() as *mut _, buf.len())
        };
        if count < 0 {
            return Err(ReadlineError::Io(io::Error::last_os_error()));
        }
        if count == 0 {
            return Ok(None);
        }
        self.input.extend_from_slice(&buf[..count as usize]);
        Ok(self.input.pop_front())
    }

    fn poll(&mut self, timeout_ms: i32) -> bool {
        if !self.input.is_empty() {
            return true;
        }
        let mut pfd = PollFd {
            fd: 0,
            events: 1,
            revents: 0,
        };
        let result = unsafe { libc_poll(&mut pfd, 1, timeout_ms) };
        result > 0 && pfd.revents != 0
    }
}

fn is_enter_event(event: &Event) -> bool {
    matches!(event, Event::Char('\r'))
}

fn csi_event(params: &str, final_byte: u8) -> Event {
    let nums: Vec<i64> = params
        .split(';')
        .map(|p| p.parse::<i64>().unwrap_or(0))
        .collect();
    let first = nums.get(0).copied().unwrap_or(0);
    let modifier = nums.get(1).copied().unwrap_or(1);
    match final_byte {
        b'A' => Event::Up,
        b'B' => Event::Down,
        b'C' => {
            if modifier >= 3 {
                Event::WordRight
            } else {
                Event::Right
            }
        }
        b'D' => {
            if modifier >= 3 {
                Event::WordLeft
            } else {
                Event::Left
            }
        }
        b'H' => Event::Home,
        b'F' => Event::End,
        b'Z' => Event::BackTab,
        b'~' => match first {
            1 | 7 => Event::Home,
            3 => Event::Delete,
            4 | 8 => Event::End,
            5 => Event::PageUp,
            6 => Event::PageDown,
            _ => Event::None,
        },
        _ => Event::None,
    }
}

fn search_prompt(search: &SearchState) -> String {
    match (search.direction, search.failed) {
        (SearchDirection::Reverse, false) => {
            format!("(reverse-i-search)`{}': ", search.query)
        }
        (SearchDirection::Reverse, true) => {
            format!("(failed reverse-i-search)`{}': ", search.query)
        }
        (SearchDirection::Forward, false) => format!("(i-search)`{}': ", search.query),
        (SearchDirection::Forward, true) => {
            format!("(failed i-search)`{}': ", search.query)
        }
    }
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn word_left(chars: &[char], cursor: usize) -> usize {
    let mut i = cursor;
    while i > 0 && !is_word_char(chars[i - 1]) {
        i -= 1;
    }
    while i > 0 && is_word_char(chars[i - 1]) {
        i -= 1;
    }
    i
}

fn word_right(chars: &[char], cursor: usize) -> usize {
    let mut i = cursor;
    while i < chars.len() && !is_word_char(chars[i]) {
        i += 1;
    }
    while i < chars.len() && is_word_char(chars[i]) {
        i += 1;
    }
    i
}

fn kill_word_left(chars: &[char], cursor: usize) -> usize {
    let mut i = cursor;
    while i > 0 && chars[i - 1].is_whitespace() {
        i -= 1;
    }
    while i > 0 && !chars[i - 1].is_whitespace() {
        i -= 1;
    }
    i
}

fn utf8_len(first: u8) -> usize {
    if first >= 0xf0 {
        4
    } else if first >= 0xe0 {
        3
    } else if first >= 0xc0 {
        2
    } else {
        0
    }
}

fn filename_candidates(chars: &[char], cursor: usize) -> Option<(usize, String, Vec<String>)> {
    const BREAK_CHARS: &str = " \t\n\"'`@$><=;|&{(";
    let mut start = cursor;
    while start > 0 {
        let c = chars[start - 1];
        if BREAK_CHARS.contains(c) {
            let mut backslashes = 0usize;
            let mut j = start - 1;
            while j > 0 && chars[j - 1] == '\\' {
                backslashes += 1;
                j -= 1;
            }
            if backslashes % 2 == 0 {
                break;
            }
        }
        start -= 1;
    }
    let original: String = chars[start..cursor].iter().collect();
    let path_word = unescape_completion(&original);
    let (dir, typed_prefix, file_prefix): (String, String, String) =
        if path_word.is_empty() {
            (".".to_owned(), String::new(), String::new())
        } else if path_word.ends_with('/') {
            let dir = if path_word == "/" {
                "/".to_owned()
            } else {
                path_word.trim_end_matches('/').to_owned()
            };
            (dir, path_word.clone(), String::new())
        } else if let Some(slash) = path_word.rfind('/') {
            let dir = if slash == 0 {
                "/".to_owned()
            } else {
                path_word[..slash].to_owned()
            };
            (
                dir,
                path_word[..=slash].to_owned(),
                path_word[slash + 1..].to_owned(),
            )
        } else {
            (".".to_owned(), String::new(), path_word.clone())
        };
    let read_dir = fs::read_dir(&dir).ok()?;
    let mut names: Vec<(String, String, bool)> = Vec::new();
    for entry in read_dir.flatten() {
        let name_os = entry.file_name();
        let Some(name) = name_os.to_str() else { continue };
        if !name.starts_with(&file_prefix) {
            continue;
        }
        let is_dir = entry
            .metadata()
            .map(|m| m.is_dir())
            .or_else(|_| fs::metadata(entry.path()).map(|m| m.is_dir()))
            .unwrap_or(false);
        names.push((name.to_owned(), escape_completion(name), is_dir));
    }
    names.sort_by(|a, b| a.0.cmp(&b.0));
    let candidates = names
        .into_iter()
        .map(|(_, escaped, is_dir)| {
            let mut candidate = format!("{}{}", typed_prefix, escaped);
            if is_dir {
                candidate.push('/');
            }
            candidate
        })
        .collect();
    Some((start, original, candidates))
}

fn unescape_completion(text: &str) -> String {
    let mut out = String::new();
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(next) = chars.peek().copied() {
                if " \t\n\"'`@$><=;|&{()\\".contains(next) {
                    chars.next();
                    out.push(next);
                    continue;
                }
            }
        }
        out.push(c);
    }
    out
}

fn escape_completion(name: &str) -> String {
    let mut out = String::new();
    for c in name.chars() {
        if " \t\n\"'`@$><=;|&{()\\".contains(c) {
            out.push('\\');
        }
        out.push(c);
    }
    out
}

#[derive(Default)]
struct Renderer {
    prev_cursor_row: usize,
    prev_total_rows: usize,
    clear_screen: bool,
}

impl Renderer {
    fn render(
        &mut self,
        out: &mut io::Stdout,
        prompt: &str,
        display: &str,
        cursor: usize,
        hint: &str,
        angle: AngleUnit,
    ) {
        let cols = terminal_columns().max(1);
        let highlighted = highlight_line(display, angle);
        let cursor_offset = display
            .chars()
            .take(cursor)
            .map(|c| c.len_utf8())
            .sum::<usize>();
        let _ = cursor_offset;
        let plain_before_cursor: String = prompt
            .chars()
            .chain(display.chars().take(cursor))
            .collect();
        let plain_total = format!("{}{}{}", prompt, display, hint);
        let target = layout(&plain_before_cursor, cols);
        let end = layout(&plain_total, cols);
        let total_rows = end.0 + 1;
        let mut buf = String::new();
        buf.push_str("\x1b[?2026h");
        if self.clear_screen {
            buf.push_str("\x1b[H\x1b[2J");
            self.prev_cursor_row = 0;
            self.prev_total_rows = 1;
            self.clear_screen = false;
        }
        buf.push('\r');
        if self.prev_cursor_row > 0 {
            buf.push_str(&format!("\x1b[{}A", self.prev_cursor_row));
        }
        if self.prev_total_rows > 1 || total_rows > 1 {
            buf.push_str("\x1b[J");
        } else {
            buf.push_str("\x1b[K");
        }
        buf.push_str(prompt);
        buf.push_str(&highlighted.replace('\n', "\r\n"));
        if !hint.is_empty() {
            buf.push_str("\x1b[90m");
            buf.push_str(&hint.replace('\n', "\r\n"));
            buf.push_str("\x1b[0m");
        }
        buf.push('\r');
        if end.0 > target.0 {
            buf.push_str(&format!("\x1b[{}A", end.0 - target.0));
        }
        if target.1 > 0 {
            buf.push_str(&format!("\x1b[{}C", target.1));
        }
        buf.push_str("\x1b[?2026l");
        let _ = out.write_all(buf.as_bytes());
        let _ = out.flush();
        self.prev_cursor_row = target.0;
        self.prev_total_rows = total_rows;
    }
}

fn layout(text: &str, cols: usize) -> (usize, usize) {
    let mut row = 0usize;
    let mut col = 0usize;
    for c in text.chars() {
        if c == '\n' {
            row += 1;
            col = 0;
        } else if c == '\r' {
            col = 0;
        } else {
            let width = char_width(c);
            if width == 0 {
                continue;
            }
            if col + width > cols {
                row += 1;
                col = width;
            } else {
                col += width;
                if col == cols {
                    row += 1;
                    col = 0;
                }
            }
        }
    }
    (row, col)
}

fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp == 0 {
        return 0;
    }
    if cp < 32 || (0x7f..0xa0).contains(&cp) {
        return 0;
    }
    if (0x300..=0x36f).contains(&cp)
        || (0x1ab0..=0x1aff).contains(&cp)
        || (0x1dc0..=0x1dff).contains(&cp)
        || (0x20d0..=0x20ff).contains(&cp)
        || (0xfe20..=0xfe2f).contains(&cp)
    {
        return 0;
    }
    if (0x1100..=0x115f).contains(&cp)
        || (0x2e80..=0xa4cf).contains(&cp)
        || (0xac00..=0xd7a3).contains(&cp)
        || (0xf900..=0xfaff).contains(&cp)
        || (0xfe30..=0xfe6f).contains(&cp)
        || (0xff00..=0xff60).contains(&cp)
        || (0xffe0..=0xffe6).contains(&cp)
        || (0x1f300..=0x1f9ff).contains(&cp)
        || (0x20000..=0x3fffd).contains(&cp)
    {
        2
    } else {
        1
    }
}

#[repr(C)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

#[repr(C)]
struct PollFd {
    fd: i32,
    events: i16,
    revents: i16,
}

extern "C" {
    fn tcgetattr(fd: i32, termios: *mut u8) -> i32;
    fn tcsetattr(fd: i32, action: i32, termios: *const u8) -> i32;
    fn cfmakeraw(termios: *mut u8);
    fn read(fd: i32, buf: *mut u8, count: usize) -> isize;
    fn poll(fds: *mut PollFd, nfds: u64, timeout: i32) -> i32;
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

fn libc_read(fd: i32, buf: *mut u8, count: usize) -> isize {
    unsafe { read(fd, buf, count) }
}

fn libc_poll(fds: *mut PollFd, nfds: u64, timeout: i32) -> i32 {
    unsafe { poll(fds, nfds, timeout) }
}

fn terminal_columns() -> usize {
    let mut winsize = Winsize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    for fd in [1, 0, 2] {
        let result = unsafe { ioctl(fd, 0x5413, &mut winsize as *mut Winsize) };
        if result == 0 && winsize.ws_col > 0 {
            return winsize.ws_col as usize;
        }
    }
    std::env::var("COLUMNS")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(80)
}

struct RawTerminal {
    original: [u8; 256],
}

impl RawTerminal {
    fn enable() -> Result<Self, ReadlineError> {
        let mut original = [0u8; 256];
        let result = unsafe { tcgetattr(0, original.as_mut_ptr()) };
        if result != 0 {
            return Err(ReadlineError::Io(io::Error::last_os_error()));
        }
        let mut raw = original;
        unsafe { cfmakeraw(raw.as_mut_ptr()) };
        let result = unsafe { tcsetattr(0, 0, raw.as_ptr()) };
        if result != 0 {
            return Err(ReadlineError::Io(io::Error::last_os_error()));
        }
        Ok(RawTerminal { original })
    }
}

impl Drop for RawTerminal {
    fn drop(&mut self) {
        unsafe { tcsetattr(0, 0, self.original.as_ptr()) };
    }
}
