#[derive(Debug, Clone, Copy)]
pub struct Config {
    pub fix: usize,
    pub radix: u32,
    pub angle: AngleUnit,
}

pub fn run_repl(config: Config) {
    let cache_dir = app_directory(cache_base_dir());
    let previous_ans_path = cache_dir.join("previous_ans.txt");
    if let Err(error) = fs::write(&previous_ans_path, "0") {
        println!("Could not write to previous_ans_path\n{:?}", error);
        process::exit(1);
    }
    let data_dir = app_directory(data_base_dir());
    let history_path = data_dir.join("history.txt");
    let mut history = History::default();
    if history.load(&history_path).is_err() {
        println!("No previous history.");
    }
    let mut editor = Editor::new(history, config.angle);
    let mut prev_ans: Option<f64> = None;
    loop {
        match editor.readline() {
            Ok(line) => {
                editor.add_history(&line);
                match eval(&line, prev_ans, config.angle) {
                    Ok(result) => {
                        println!("{}", format_number(result, config.radix, config.fix));
                        let rounded = rounded_decimal_value(result, config.fix);
                        prev_ans = Some(rounded);
                        if let Err(error) =
                            fs::write(&previous_ans_path, format!("{}\n", rounded))
                        {
                            println!("Error while writing previous answer to file: {}", error);
                        }
                    }
                    Err(error) => println!("{}", error),
                }
            }
            Err(ReadlineError::Interrupted) => {
                println!("CTRL-C");
                break;
            }
            Err(ReadlineError::Eof) => break,
            Err(error) => {
                println!("Error: {:?}", error);
                break;
            }
        }
    }
    editor.save_history(&history_path).unwrap();
}
