mod editor;
mod error;
mod format;
mod fxns;
mod highlight;
mod history;
mod lex;
mod parse;
mod repl;

use clap::{Arg, Command};
use format::format_number;
use fxns::AngleUnit;
use parse::eval;
use repl::{run_repl, Config};
use std::process;

fn build_cli() -> Command {
    Command::new("eva")
        .version("0.3.1")
        .about("Calculator REPL similar to bc(1)")
        .arg(
            Arg::new("fix")
                .short('f')
                .long("fix")
                .value_name("FIX")
                .help("Number of decimal places in output (1 - 64)")
                .default_value("10")
                .value_parser(clap::value_parser!(u64).range(1..=64)),
        )
        .arg(
            Arg::new("base")
                .short('b')
                .long("base")
                .value_name("RADIX")
                .help("Radix of calculation output (1 - 36)")
                .default_value("10")
                .value_parser(clap::value_parser!(u64).range(1..=36)),
        )
        .arg(
            Arg::new("angle_unit")
                .short('a')
                .long("angle_unit")
                .value_name("angle_unit")
                .help("Angle unit")
                .default_value("degree")
                .value_parser(["degree", "radian", "gradian"]),
        )
        .arg(
            Arg::new("INPUT")
                .help("Optional expression string to run eva in command mode"),
        )
}

fn main() {
    let matches = build_cli().get_matches();
    let fix = *matches.get_one::<u64>("fix").unwrap() as usize;
    let radix = *matches.get_one::<u64>("base").unwrap() as u32;
    let angle = match matches
        .get_one::<String>("angle_unit")
        .map(|s| s.as_str())
        .unwrap_or("degree")
    {
        "radian" => AngleUnit::Radian,
        "gradian" => AngleUnit::Gradian,
        _ => AngleUnit::Degree,
    };
    let config = Config { fix, radix, angle };
    if let Some(input) = matches.get_one::<String>("INPUT") {
        if !input.is_empty() {
            match eval(input, Some(0.0), angle) {
                Ok(result) => println!("{}", format_number(result, radix, fix)),
                Err(error) => {
                    eprintln!("{}", error);
                    process::exit(1);
                }
            }
            return;
        }
    }
    run_repl(config);
}
