import pty,os,time,select,shutil
def run(bin_path,home,chunks):
 shutil.rmtree(home,ignore_errors=True);os.makedirs(home)
 pid,fd=pty.fork()
 if pid==0:
  os.chdir('/workspace');os.environ['HOME']=home;os.environ['TERM']='xterm-256color';os.execv(bin_path,[bin_path])
 out=b''
 def drain():
  nonlocal out;end=time.time()+.4
  while time.time()<end:
   r,_,_=select.select([fd],[],[],.05)
   if r:
    try:d=os.read(fd,100000)
    except:break
    if not d:break
    out+=d;end=time.time()+.12
 drain()
 for chunk in chunks:
  try:os.write(fd,chunk)
  except:break
  drain()
 try:os.write(fd,b'\x03');drain()
 except:pass
 return out

